  const { parse, status, error } = useMatchbox(loadMoney);
  const [message, setMessage] = useState("");

  return (
    <div>
      <button
        disabled={status !== "ready"}
        onClick={async () => {
          try {
            const result = await parse("twenty dollars");
            setMessage(
              result.status === "ok"
                ? `${result.value.amount} ${result.value.currency}`
